// Rules mirrored from packages/automation/src/vacancy.ts and packages/schemas/src/content.ts (vacancyDisplay):
//   - a vacancy shown as available needs a lastVerifiedAt; older than VACANCY_STALE_DAYS (strictly more than 14 days) is shown as unconfirmed
//   - "temporarilyUnavailable" and "noLongerAvailable" do not depend on verification age
// This node only reports. It never edits a vacancy and never marks one as available.
const VACANCY_STALE_DAYS = 14;
const DAY_MS = 86400000;
const nowMs = Date.now();

const input = $input.first().json || {};
const rows = input.apiVersion === '1' && Array.isArray(input.data) ? input.data : null;

if (!rows) {
  return [{
    json: {
      hasIssues: true,
      count: 0,
      flagged: [],
      notifySubject: 'Vacancy monitor could not read the vacancies API',
      notifyText: 'The daily vacancy check could not read a valid response from the vacancies API, so vacancy freshness was not checked. Check the site and the monitor.',
    },
  }];
}

const flagged = [];
for (const v of rows) {
  if (!v || (v.availability !== 'available' && v.availability !== 'unconfirmed')) continue;
  const verifiedMs = v.lastVerifiedAt ? Date.parse(v.lastVerifiedAt) : NaN;
  const ageDays = Number.isNaN(verifiedMs) ? null : (nowMs - verifiedMs) / DAY_MS;
  let problem = '';
  if (!v.lastVerifiedAt) problem = 'never_verified';
  else if (ageDays === null) problem = 'verification_date_unreadable';
  else if (ageDays > VACANCY_STALE_DAYS) problem = 'verification_older_than_' + VACANCY_STALE_DAYS + '_days';
  else if (v.availability === 'unconfirmed') problem = 'shown_as_unconfirmed';
  if (!problem) continue;
  flagged.push({
    id: v.id,
    suburb: v.suburb,
    region: v.region,
    type: v.vacancyType,
    shownAs: v.availability,
    lastVerifiedAt: v.lastVerifiedAt || null,
    ageDays: ageDays === null ? null : Math.floor(ageDays),
    problem,
  });
}

const lines = flagged.map((f) => '- ' + f.id + ' (' + f.suburb + ', ' + f.region + '): ' + f.problem + (f.ageDays === null ? '' : ', last verified ' + f.ageDays + ' days ago') + ', shown on the site as ' + f.shownAs);
return [{
  json: {
    hasIssues: flagged.length > 0,
    count: flagged.length,
    flagged,
    notifySubject: 'Vacancy board: ' + flagged.length + ' vacancy listing(s) need verification',
    notifyText: [
      'These vacancy listings are unconfirmed or were last verified more than ' + VACANCY_STALE_DAYS + ' days ago:',
      ...lines,
      '',
      'Only a person who knows the real situation can confirm availability. Update the source record, then the site will show the new state after the next build.',
      'Note: the site computes "available" at build time. A listing that still reads "available" above has not been rebuilt since it went stale.',
    ].join('\n'),
  },
}];
